// Auto-generated by Cloud Payments. Do not edit — regenerated on enable.
//
// Sealed catalog data client. Use these helpers to build product list and detail
// pages; they call the platform catalog API (only products configured in
// More → Cloud → Payments for this project). Do NOT hand-roll product/GHL API calls

const apiUrl = (import.meta.env["VITE_CATALOG_API_URL"] ?? "").replace(/\/$/, "");
const projectId = import.meta.env["VITE_PROJECT_ID"] ?? "";

export interface CatalogPrice {
  id: string;
  name?: string;
  /** Major currency units: 25 means $25.00, not cents. Never divide by 100. */
  amount: number;
  currency?: string;
  type?: string; // one_time | recurring
  /** Set on a subscription price (type "recurring"). */
  recurring?: CatalogRecurring;
  compare_at_price?: number;
  variant_option_ids?: string[];
  /** None left: show "Sold out" and never let the buyer add or buy it. */
  sold_out?: boolean;
}

/** A subscription price's billing terms: "$9 / month · 7-day free trial". */
export interface CatalogRecurring {
  interval: string; // day | week | month | year
  interval_count: number; // bills every interval_count intervals
  trial_days?: number;
  setup_fee?: number; // charged once, with the first payment
  total_cycles?: number; // number of payments; absent = until cancelled
}

export interface CatalogVariantOption {
  id: string;
  name: string;
}

export interface CatalogVariant {
  id: string;
  name: string;
  options: CatalogVariantOption[];
}

export interface CatalogMedia {
  url: string;
  price_ids?: string[];
}

export interface CatalogProduct {
  id: string;
  name: string;
  description?: string;
  product_type?: string;
  slug?: string;
  image?: string;
  images?: string[];
  currency?: string;
  has_variants: boolean;
  prices: CatalogPrice[];
  variants?: CatalogVariant[];
  medias?: CatalogMedia[];
}

export interface CatalogPage {
  products: CatalogProduct[];
  total: number;
  limit: number;
  offset: number;
}

export interface CatalogListParams {
  search?: string | undefined;
  limit?: number | undefined;
  offset?: number | undefined;
}

function base(): string {
  if (!apiUrl || !projectId) {
    throw new Error("Catalog API is not configured.");
  }
  return `${apiUrl}/public/catalog/projects/${projectId}`;
}

/** List store products (paginated, each enriched with prices/variants). */
export async function listCatalogProducts(params: CatalogListParams = {}): Promise<CatalogPage> {
  const query = new URLSearchParams();
  if (params.search) query.set("search", params.search);
  if (params.limit != null) query.set("limit", String(params.limit));
  if (params.offset != null) query.set("offset", String(params.offset));
  const qs = query.toString();
  const res = await fetch(`${base()}/items${qs ? `?${qs}` : ""}`);
  if (!res.ok) {
    throw new Error(`Failed to load products (${res.status})`);
  }
  return (await res.json()) as CatalogPage;
}

/** Fetch one product's full detail (prices + variants) for a detail page. */
export async function getCatalogProduct(productId: string): Promise<CatalogProduct> {
  const res = await fetch(`${base()}/product/${encodeURIComponent(productId)}`);
  if (!res.ok) {
    throw new Error(`Failed to load product (${res.status})`);
  }
  return (await res.json()) as CatalogProduct;
}
